__cleanup:
$used = @()
if (Get-Module -ListAvailable WebAdministration) { Import-Module WebAdministration; $used += @(Get-ChildItem IIS:\SslBindings -ErrorAction SilentlyContinue | ForEach-Object { $_.Thumbprint }) }
$r = Run-Native 'netsh.exe' @('http', 'show', 'sslcert')
$used += @([regex]::Matches($r.out, '(?im):\s*([0-9a-f]{40})\s*$') | ForEach-Object { $_.Groups[1].Value })
try { $used += @(Get-CimInstance -Namespace root/cimv2/TerminalServices -ClassName Win32_TSGeneralSetting -ErrorAction Stop | ForEach-Object { $_.SSLCertificateSHA1Hash }) } catch { }
$used += @(Get-ChildItem 'HKLM:\SOFTWARE\Microsoft\Microsoft SQL Server' -ErrorAction SilentlyContinue | ForEach-Object { $p = Join-Path $_.PSPath 'MSSQLServer\SuperSocketNetLib'; if (Test-Path -LiteralPath $p) { (Get-ItemProperty -LiteralPath $p -ErrorAction SilentlyContinue).Certificate } })
try { $used += @(Get-ChildItem WSMan:\localhost\Listener -ErrorAction Stop | ForEach-Object { (Get-Item -Path ('WSMan:\localhost\Listener\' + $_.Name + '\CertificateThumbprint')).Value }) } catch { }
$used = @($used | Where-Object { $_ } | ForEach-Object { ([string]$_).ToUpperInvariant() })
$old = Get-ChildItem $store | Where-Object { $_.FriendlyName -match ('^' + [regex]::Escape('acme-www-') + '\d{8}-[0-9a-f]+$') -and $_.Thumbprint -ne $thumb } | Sort-Object NotBefore -Descending | Select-Object -Skip 2
foreach ($x in $old) { if ($used -contains $x.Thumbprint) { Say warn ('the old ' + $x.Thumbprint + ' is still used: kept') } else { Remove-Item -LiteralPath $x.PSPath; Say info ('removed the old ' + $x.Thumbprint) } }

