try { $k = Get-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Microsoft SQL Server\Instance Names\SQL' -ErrorAction SilentlyContinue; $n = @(); if ($k) { $n = @($k.PSObject.Properties | Where-Object { $_.Name -notlike 'PS*' } | ForEach-Object { $_.Name }) }; R sql ($n.Count -gt 0) ($n -join ', ') } catch { R sql $false '?' }
try { R ldaps (HasSvc 'NTDS') '' } catch { R ldaps $false '?' }
try { $n = 0; if (HasSvc 'WinRM') { try { $n = @(Get-ChildItem WSMan:\localhost\Listener -ErrorAction Stop | Where-Object { $_.Keys -contains 'Transport=HTTPS' }).Count } catch { } }; R winrm (HasSvc 'WinRM') ([string]$n + ' HTTPS listener(s)') } catch { R winrm $false '?' }
try { R sstp ((HasSvc 'RemoteAccess') -and (HasMod 'RemoteAccess')) '' } catch { R sstp $false '?' }
try { $c = Get-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Microsoft\IIS\CentralCertProvider' -ErrorAction SilentlyContinue; $d = 'not set up'; if ($c -and $c.Enabled -eq 1) { $d = [string]$c.CertStoreLocation }; R ccs (HasSvc 'W3SVC') $d } catch { R ccs $false '?' }
try { R ftp (HasSvc 'ftpsvc') '' } catch { R ftp $false '?' }
