try { if (HasSvc 'WindowsAdminCenter') { R wac $true '2410 or later' } elseif (HasSvc 'ServerManagementGateway') { R wac $true 'before 2410' } else { R wac $false '' } } catch { R wac $false '?' }

__head:
$thumb = 'ABABABABABABABABABABABABABABABABABABABAB'
$prefix = 'acme-o''x-'
$store = 'Cert:\LocalMachine\My'
$cert = Get-Item -LiteralPath (Join-Path $store $thumb) -ErrorAction SilentlyContinue
if (-not $cert) { throw ('the new certificate ' + $thumb + ' is not in LocalMachine\My') }
function Say([string]$l, [string]$w) { Write-Output ('STEP ' + $l + ' ' + $w) }
function Run-Native([string]$exe, [string[]]$a) { $ErrorActionPreference = 'Continue'; $o = & $exe @a 2>&1 | ForEach-Object { "$_" }; [pscustomobject]@{ rc = $LASTEXITCODE; out = ($o -join "`n") } }
function Need-Module([string]$m, [string]$r) {
  if (-not (Get-Module -ListAvailable -Name $m)) { throw ($r + ': the PowerShell module ' + $m + ' is not on this server - is the role installed?') }
  Import-Module -Name $m -ErrorAction Stop -WarningAction SilentlyContinue -DisableNameChecking
}
function Need-Service([string]$n, [string]$r) {
  $x = Get-Service -Name $n -ErrorAction SilentlyContinue
  if (-not $x) { throw ($r + ': the service ' + $n + ' is not on this server - is the role installed?') }
  $x
}
function Restart-Role([string]$n) {
  $deps = @((Get-Service -Name $n).DependentServices | Where-Object { $_.Status -eq 'Running' })
  Restart-Service -Name $n -Force -ErrorAction Stop
  foreach ($d in $deps) { if ((Get-Service -Name $d.Name).Status -ne 'Running') { Start-Service -Name $d.Name -ErrorAction Stop } }
  $also = ''; if ($deps) { $also = ' (and ' + (($deps | ForEach-Object { $_.Name }) -join ', ') + ')' }
  Say ok ('restarted ' + $n + $also)
}
function Grant-KeyRead($c, [string]$who) {
  if ($who -match '^(LocalSystem|NT AUTHORITY\\SYSTEM)$') { Say info ('read on the key: ' + $who + ' (SYSTEM) has it'); return }
  if ($who -match '^(NT AUTHORITY\\)?NetworkService$') { $who = 'NT AUTHORITY\NETWORK SERVICE' }
  if ($who -match '^(NT AUTHORITY\\)?LocalService$') { $who = 'NT AUTHORITY\LOCAL SERVICE' }
  $k = $null; $name = $null
  try { $k = [System.Security.Cryptography.X509Certificates.RSACertificateExtensions]::GetRSAPrivateKey($c) } catch { }
  if (-not $k) { try { $k = [System.Security.Cryptography.X509Certificates.ECDsaCertificateExtensions]::GetECDsaPrivateKey($c) } catch { } }
  if ($k -and ($k.PSObject.Properties.Name -contains 'Key') -and $k.Key) { $name = $k.Key.UniqueName } elseif ($k -and $k.CspKeyContainerInfo) { $name = $k.CspKeyContainerInfo.UniqueKeyContainerName }
  if (-not $name) { throw ('the private key of ' + $c.Thumbprint + ' was not found') }
  $files = @(@("$env:ProgramData\Microsoft\Crypto\RSA\MachineKeys", "$env:ProgramData\Microsoft\Crypto\Keys") | ForEach-Object { Join-Path $_ $name } | Where-Object { Test-Path -LiteralPath $_ })
  if (-not $files) { throw ('the key file ' + $name + ' is not under ProgramData\Microsoft\Crypto') }
  try { $sid = (New-Object System.Security.Principal.NTAccount($who)).Translate([System.Security.Principal.SecurityIdentifier]).Value } catch { throw ('the account ' + $who + ' is not known here') }
  foreach ($f in $files) { $r = Run-Native 'icacls.exe' @($f, '/grant', ('*' + $sid + ':(R)')); if ($r.rc -ne 0) { throw ('icacls ' + $f + ': ' + $r.out) } }
  Say ok ('read on the key for ' + $who)
}

