exchange/all:
if (-not (Get-Command Enable-ExchangeCertificate -ErrorAction SilentlyContinue)) {
  $snap = 'Microsoft.Exchange.Management.PowerShell.SnapIn'
  if (-not (Get-PSSnapin -Registered -Name $snap -ErrorAction SilentlyContinue)) { throw 'Exchange: the Exchange Management Shell is not on this server - is Exchange installed?' }
  Add-PSSnapin $snap
}
$ec = Get-ExchangeCertificate -Thumbprint $thumb -ErrorAction Stop
$have = @(([string]$ec.Services) -split '[,\s]+' | Where-Object { $_ })
$want = @('IIS', 'SMTP', 'IMAP', 'POP', 'UM', 'UMCallRouter')
$missing = @($want | Where-Object { $have -notcontains $_ })
$changed = $false
if (-not $missing) { Say ok ('Exchange already uses it for ' + ($want -join ', ')) } else {
  Enable-ExchangeCertificate -Thumbprint $thumb -Services ($want -join ',') -Force -Confirm:$false -ErrorAction Stop; $changed = $true
  Say ok ('Exchange uses it for ' + ($want -join ', ')) }
if ($changed) { foreach ($n in @('MSExchangeIMAP4', 'MSExchangeIMAP4BE')) { if (Get-Service -Name $n -ErrorAction SilentlyContinue) { Restart-Role $n } } }
if ($changed) { foreach ($n in @('MSExchangePOP3', 'MSExchangePOP3BE')) { if (Get-Service -Name $n -ErrorAction SilentlyContinue) { Restart-Role $n } } }
foreach ($x in @(Get-ExchangeCertificate | Where-Object { $_.Thumbprint -ne $thumb -and $_.FriendlyName -match ('^' + [regex]::Escape($prefix) + '\d{8}-[0-9a-f]+$') })) {
  if ([string]$x.Services -eq 'None') { Remove-ExchangeCertificate -Thumbprint $x.Thumbprint -Confirm:$false -ErrorAction Stop; Say ok ('Exchange: removed the old ' + $x.Thumbprint) }
  else { Say warn ('Exchange: the old ' + $x.Thumbprint + ' is still bound to ' + $x.Services + ' - kept') }
}

