ldaps/all:
Need-Service 'NTDS' 'LDAPS' | Out-Null
if (-not (Get-Command ldifde.exe -ErrorAction SilentlyContinue)) { throw 'LDAPS: ldifde.exe is not on this server - is it a domain controller?' }
$src = 'HKLM:\SOFTWARE\Microsoft\SystemCertificates\MY\Certificates\' + $thumb
$dst = 'HKLM:\SOFTWARE\Microsoft\Cryptography\Services\NTDS\SystemCertificates\My\Certificates'
if (-not (Test-Path -LiteralPath $src)) { throw ('LDAPS: ' + $src + ' is not there') }
if (-not (Test-Path -LiteralPath $dst)) { New-Item -Path $dst -Force | Out-Null }
if (Test-Path -LiteralPath (Join-Path $dst $thumb)) { Say ok 'LDAPS: already in NTDS\Personal' } else { Copy-Item -LiteralPath $src -Destination $dst -Recurse -ErrorAction Stop; Say ok 'LDAPS: put into NTDS\Personal' }
$olds = @(Get-ChildItem $store | Where-Object { $_.FriendlyName -match ('^' + [regex]::Escape($prefix) + '\d{8}-[0-9a-f]+$') -and $_.Thumbprint -ne $thumb } | ForEach-Object { $_.Thumbprint })
foreach ($x in @(Get-ChildItem -LiteralPath $dst)) { if ($olds -contains $x.PSChildName) { Remove-Item -LiteralPath $x.PSPath -Recurse -Force; Say info ('LDAPS: the old ' + $x.PSChildName + ' left NTDS\Personal') } }
$ldf = Join-Path $env:TEMP ('acme-ldaps-' + [guid]::NewGuid().ToString('N') + '.ldf')
Set-Content -LiteralPath $ldf -Value "dn:`r`nchangetype: modify`r`nadd: renewServerCertificate`r`nrenewServerCertificate: 1`r`n-`r`n" -Encoding ASCII
try { $r = Run-Native 'ldifde.exe' @('-i', '-f', $ldf) } finally { Remove-Item -LiteralPath $ldf -Force -ErrorAction SilentlyContinue }
if ($r.rc -ne 0) { throw ('LDAPS: ldifde could not ask for renewServerCertificate: ' + $r.out) }
Say ok 'LDAPS: the domain controller took the certificate (renewServerCertificate)'

