if (-not $m) { throw 'Skype for Business: neither the SkypeForBusiness nor the Lync module is on this server - is it installed?' }
Import-Module -Name $m -ErrorAction Stop -WarningAction SilentlyContinue
$cur = @(Get-CsCertificate -ErrorAction Stop)
$changed = $false
foreach ($ty in @('Default', 'WebServicesInternal', 'WebServicesExternal')) {
  if (@($cur | Where-Object { [string]$_.Use -eq $ty -and $_.Thumbprint -eq $thumb }).Count) { Say ok ('Skype for Business ' + $ty + ' already uses it'); continue }
  Set-CsCertificate -Type $ty -Thumbprint $thumb -Confirm:$false -ErrorAction Stop; $changed = $true
  Say ok ('Skype for Business ' + $ty + ' uses it')
}
if ($changed) { Stop-CsWindowsService -ErrorAction Stop; Start-CsWindowsService -ErrorAction Stop; Say ok 'Skype for Business services restarted' }

