rds/all:
Need-Module 'RemoteDesktop' 'Remote Desktop Services'
$broker = 'cb''1.example.test'
$pfxpw = ConvertTo-SecureString -String 'pfx''pw' -AsPlainText -Force
foreach ($r in @('RDGateway', 'RDWebAccess', 'RDPublishing', 'RDRedirector')) {
  try { $cur = Get-RDCertificate -Role $r -ConnectionBroker $broker -ErrorAction Stop } catch { throw ('Remote Desktop Services: the Connection Broker ' + $broker + ' could not be asked: ' + $_.Exception.Message) }
  if ($cur -and $cur.Thumbprint -eq $thumb) { Say ok ('RDS ' + $r + ' already uses it'); continue }
  Set-RDCertificate -Role $r -ImportPath 'C:/Windows/Temp/r.pfx' -Password $pfxpw -ConnectionBroker $broker -Force -ErrorAction Stop
  Say ok ('RDS ' + $r + ' uses it')
}

