if (-not (Test-Path -LiteralPath $map)) { throw 'SQL Server: no instance is installed on this server' }
$names = Get-ItemProperty -LiteralPath $map
$id = $names.$inst
if (-not $id) { throw ('SQL Server: there is no instance ' + $inst + '; there are: ' + (($names.PSObject.Properties | Where-Object { $_.Name -notlike 'PS*' } | ForEach-Object { $_.Name }) -join ', ')) }
$key = 'HKLM:\SOFTWARE\Microsoft\Microsoft SQL Server\' + $id + '\MSSQLServer\SuperSocketNetLib'
if (-not (Test-Path -LiteralPath $key)) { throw ('SQL Server: ' + $key + ' is not there') }
if ($inst -eq 'MSSQLSERVER') { $svcName = 'MSSQLSERVER' } else { $svcName = 'MSSQL$' + $inst }
$svc = Get-CimInstance -ClassName Win32_Service -Filter ("Name='" + $svcName + "'")
if (-not $svc) { throw ('SQL Server: the service ' + $svcName + ' is not there') }
Grant-KeyRead $cert $svc.StartName
$changed = $false
$want = $thumb.ToLowerInvariant()
$cur = [string](Get-ItemProperty -LiteralPath $key -ErrorAction SilentlyContinue).Certificate
if ($cur -ceq $want) { Say ok ('SQL Server ' + $inst + ' already uses it') } else {
  New-ItemProperty -LiteralPath $key -Name 'Certificate' -Value $want -PropertyType String -Force | Out-Null; $changed = $true; Say ok ('SQL Server ' + $inst + ' uses it') }
$fe = (Get-ItemProperty -LiteralPath $key -ErrorAction SilentlyContinue).ForceEncryption
if ($fe -ne 0) { New-ItemProperty -LiteralPath $key -Name 'ForceEncryption' -Value 0 -PropertyType DWord -Force | Out-Null; $changed = $true; Say ok 'SQL Server ForceEncryption off' }
if ($changed) { Restart-Role $svcName }

