wac/all:
$new = Get-Service -Name 'WindowsAdminCenter' -ErrorAction SilentlyContinue
$old = Get-Service -Name 'ServerManagementGateway' -ErrorAction SilentlyContinue
if ($new) {
  $mod = Get-Module -ListAvailable -Name 'Microsoft.WindowsAdminCenter.Configuration' | Select-Object -First 1
  if (-not $mod) { $psd = Join-Path $env:ProgramFiles 'WindowsAdminCenter\PowerShellModules\Microsoft.WindowsAdminCenter.Configuration\Microsoft.WindowsAdminCenter.Configuration.psd1'; if (Test-Path -LiteralPath $psd) { $mod = $psd } else { throw 'Windows Admin Center: the module Microsoft.WindowsAdminCenter.Configuration is not there' } }
  Import-Module $mod -ErrorAction Stop -WarningAction SilentlyContinue -DisableNameChecking
  $subj = $cert.GetNameInfo([System.Security.Cryptography.X509Certificates.X509NameType]::SimpleName, $false)
  $cmd = Get-Command Set-WACCertificateSubjectName -ErrorAction Stop
  $a = @{ SubjectName = $subj }
  if ($cmd.Parameters.ContainsKey('Thumbprint')) { $a['Thumbprint'] = $thumb }
  Set-WACCertificateSubjectName @a -ErrorAction Stop
  if (Get-Command Set-WACCertificateAcl -ErrorAction SilentlyContinue) { Set-WACCertificateAcl -SubjectName $subj -ErrorAction Stop }
  Say ok ('Windows Admin Center uses it (' + $subj + ')')
  Restart-Role 'WindowsAdminCenter'
} elseif ($old) {
  $port = 6516
  if (-not $port) { $port = [int](Get-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Microsoft\ServerManagementGateway' -ErrorAction SilentlyContinue).SmePort }
  if (-not $port) { $port = 443 }
  $r = Run-Native 'netsh.exe' @('http', 'show', 'sslcert', ('ipport=0.0.0.0:' + $port))
  if ($r.out -match $thumb) { Say ok ('Windows Admin Center (older) already uses it on ' + $port) } else {
    $msi = 'C:\i\wac.msi'
    if (-not $msi) { throw 'Windows Admin Center: this is a version before 2410 - give the path of its .msi (Installer) to set the certificate' }
    if (-not (Test-Path -LiteralPath $msi)) { throw ('Windows Admin Center: ' + $msi + ' is not there') }
    $log = Join-Path $env:TEMP 'acme-wac-msi.log'
    $p = Start-Process -FilePath 'msiexec.exe' -ArgumentList @('/i', ('"' + $msi + '"'), '/qn', '/L*v', ('"' + $log + '"'), ('SME_PORT=' + $port), ('SME_THUMBPRINT=' + $thumb), 'SSL_CERTIFICATE_OPTION=installed') -Wait -PassThru
    if ($p.ExitCode -ne 0 -and $p.ExitCode -ne 3010) { throw ('Windows Admin Center: msiexec ended with ' + $p.ExitCode + ' (its log: ' + $log + ')') }
    Say ok ('Windows Admin Center (older) uses it on ' + $port) }
} else { throw 'Windows Admin Center is not on this server (no service WindowsAdminCenter or ServerManagementGateway)' }

