$cur = @(Get-WebApplicationProxySslCertificate -ErrorAction Stop)
$olds = @($cur | ForEach-Object { [string]$_.CertificateHash } | Where-Object { $_ -and $_ -ne $thumb })
$olds += @(Get-ChildItem $store | Where-Object { $_.FriendlyName -match ('^' + [regex]::Escape($prefix) + '\d{8}-[0-9a-f]+$') -and $_.Thumbprint -ne $thumb } | ForEach-Object { $_.Thumbprint })
if ($cur.Count -and -not @($cur | Where-Object { [string]$_.CertificateHash -ne $thumb }).Count) { Say ok 'Web Application Proxy already uses it' } else {
