winrm/all:
Need-Service 'WinRM' 'WinRM HTTPS' | Out-Null
$changed = $false
$ls = @(Get-ChildItem -Path WSMan:\localhost\Listener | Where-Object { $_.Keys -contains 'Transport=HTTPS' })
foreach ($l in $ls) {
  $p = 'WSMan:\localhost\Listener\' + $l.Name + '\CertificateThumbprint'
  $cur = [string](Get-Item -Path $p).Value
  if ($cur -eq $thumb) { Say ok ('WinRM ' + $l.Name + ' already uses it') } else { Set-Item -Path $p -Value $thumb -Force -ErrorAction Stop; $changed = $true; Say ok ('WinRM ' + $l.Name + ' uses it') }
}
$h = 'win.example.test'
if (-not $ls) { New-Item -Path WSMan:\localhost\Listener -Transport HTTPS -Address * -HostName $h -CertificateThumbPrint $thumb -Force -ErrorAction Stop | Out-Null; $changed = $true; Say ok ('WinRM: an HTTPS listener for ' + $h + ' was made') }
if (Get-NetFirewallRule -Name 'acme-WinRM-HTTPS-In' -ErrorAction SilentlyContinue) { Say ok 'firewall: 5986 already open' } else {
  New-NetFirewallRule -Name 'acme-WinRM-HTTPS-In' -DisplayName 'Windows Remote Management (HTTPS-In, acme)' -Direction Inbound -Protocol TCP -LocalPort 5986 -Action Allow -Profile Any -ErrorAction Stop | Out-Null; Say ok 'firewall: 5986 open' }
if ($changed) { Restart-Role 'WinRM' }

